(() => {
  'use strict';
  const UNITS={all:'八單元混合','1':'最大公因數與最小公倍數','2':'分數除法','3':'小數除法','4':'比與比值','5':'兩量關係','6':'圓周長與扇形周長','7':'放大、縮小與比例尺','8':'怎樣解題'};
  const MODES={treasure:{name:'數學寶箱王',count:1,icon:'🎁',points:100},duel:{name:'閃電擂台',count:2,icon:'⚔️',points:100},boss:{name:'三勇士打魔王',count:3,icon:'🐉',points:100}};
  const KEY='mathArena115';
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  const saved=JSON.parse(localStorage.getItem(KEY)||'{}');
  const state={mode:saved.settings?.mode||'treasure',difficulty:saved.settings?.difficulty||'normal',seconds:Number(saved.settings?.seconds||60),unit:saved.settings?.unit||'all',names:saved.settings?.names||['第一組','第二組','第三組','第四組','第五組','第六組'],round:0,question:null,used:new Set(),players:[],groupIndex:0,remaining:60,running:false,timer:null,revealed:false,selectedPlayer:0,sound:saved.settings?.sound!==false,reduced:saved.settings?.reduced||false,records:saved.records||[]};
  let audio;
  function persist(){localStorage.setItem(KEY,JSON.stringify({settings:{mode:state.mode,difficulty:state.difficulty,seconds:state.seconds,unit:state.unit,names:state.names,sound:state.sound,reduced:state.reduced},records:state.records}))}
  function tone(freq=600,duration=.08){if(!state.sound)return;try{audio=audio||new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=freq;g.gain.setValueAtTime(.06,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.start();o.stop(audio.currentTime+duration)}catch{}}
  function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),1800)}
  function settingsToUI(){$('#unitSelect').value=state.unit;$('#timeSelect').value=String(state.seconds);$('#namesInput').value=state.names.join(', ');$$('[data-difficulty]').forEach(b=>b.classList.toggle('active',b.dataset.difficulty===state.difficulty));$$('.mode-card').forEach(b=>{const on=b.dataset.mode===state.mode;b.classList.toggle('selected',on);b.setAttribute('aria-checked',on)});$('#soundBtn').textContent=state.sound?'🔊 音效':'🔇 靜音';$('#soundBtn').setAttribute('aria-pressed',state.sound);$('#motionBtn').textContent=state.reduced?'◌ 簡化動畫':'✨ 動畫';$('#motionBtn').setAttribute('aria-pressed',state.reduced);document.body.classList.toggle('reduced-motion',state.reduced);$('#recordCount').textContent=state.records.length}
  function available(){let pool=QUESTION_BANK.filter(q=>(state.unit==='all'||q.unit===state.unit)&&q.difficulty===state.difficulty);let fresh=pool.filter(q=>!state.used.has(q.id));if(!fresh.length){state.used.clear();fresh=pool;toast('此篩選題目已用完，題庫重新洗牌')};return fresh}
  function draw(){const pool=available();state.question=pool[Math.floor(Math.random()*pool.length)];state.used.add(state.question.id);state.revealed=false;$('#answerPanel').hidden=true;$('#questionText').textContent=state.question.prompt;$('#answerText').textContent=state.question.answer;$('#explanationText').textContent=state.question.explanation;$('#questionNumber').textContent=`QUESTION ${String(state.round).padStart(2,'0')}`;$('#unitLabel').textContent=`第 ${state.question.unit} 單元｜${UNITS[state.question.unit]}`}
  function makePlayers(){const c=MODES[state.mode].count;state.players=[];for(let i=0;i<c;i++){const idx=(state.groupIndex*c+i)%state.names.length;state.players.push({name:state.names[idx]||`選手 ${i+1}`,score:0,judged:null})}}
  function renderPlayers(){const labels=['選手 A','選手 B','選手 C'];$('#scoreboard').innerHTML=state.players.map((p,i)=>`<article class="player-card ${i===state.selectedPlayer?'active':''} ${p.judged||''}" data-player="${i}"><small>${labels[i]}</small><strong>${escapeHtml(p.name)}</strong><span class="score">${p.score} 分</span></article>`).join('');$('#scoreControls').innerHTML=state.players.map((p,i)=>`<button data-score-player="${i}" class="${i===state.selectedPlayer?'selected':''}" title="選擇${labels[i]}">${i+1}號 ${p.judged==='correct'?'✓':p.judged==='wrong'?'✗':'±'}</button>`).join('');$$('[data-player],[data-score-player]').forEach(el=>el.onclick=()=>{state.selectedPlayer=Number(el.dataset.player??el.dataset.scorePlayer);renderPlayers()})}
  function renderMeta(){const m=MODES[state.mode];$('#modeLabel').textContent=m.name;$('#roundLabel').textContent=`第 ${state.round} 回合`;$('#difficultyLabel').textContent={easy:'簡單',normal:'普通',hard:'困難'}[state.difficulty];$('#modeVisual').textContent=m.icon;$('#timer strong').textContent=state.remaining;renderPlayers()}
  function resetTimer(){clearInterval(state.timer);state.running=false;state.remaining=state.seconds;$('#timerBtn').innerHTML='▶ 開始計時 <kbd>Space</kbd>';paintTimer()}
  function paintTimer(){$('#timer strong').textContent=state.remaining;$('#timer').classList.toggle('warning',state.remaining<=15&&state.remaining>5);$('#timer').classList.toggle('danger',state.remaining<=5)}
  function toggleTimer(){if(state.running){clearInterval(state.timer);state.running=false;$('#timerBtn').innerHTML='▶ 繼續計時 <kbd>Space</kbd>';return}state.running=true;$('#timerBtn').innerHTML='Ⅱ 暫停計時 <kbd>Space</kbd>';tone(520);state.timer=setInterval(()=>{state.remaining--;paintTimer();if(state.remaining<=0){clearInterval(state.timer);state.running=false;$('#timerBtn').innerHTML='時間到 <kbd>Space</kbd>';tone(180,.4);toast('時間到！請老師公布答案並判分')}},1000)}
  function reveal(){state.revealed=!state.revealed;$('#answerPanel').hidden=!state.revealed;$('#revealBtn').innerHTML=state.revealed?'🙈 隱藏答案 <kbd>A</kbd>':'👁 公布答案 <kbd>A</kbd>';tone(state.revealed?720:420)}
  function judge(correct){const p=state.players[state.selectedPlayer];const delta=correct?MODES[state.mode].points:-50;p.score=Math.max(0,p.score+delta);p.judged=correct?'correct':'wrong';renderPlayers();if(correct){$('#modeVisual').classList.remove('reward');void $('#modeVisual').offsetWidth;$('#modeVisual').classList.add('reward');tone(880,.18);toast(state.mode==='boss'?'攻擊成功！魔王受到 100 傷害':'答對了！獲得 100 分')}else{tone(220,.18);toast('已標記答錯，扣 50 分')};persist()}
  function newGame(){state.unit=$('#unitSelect').value;state.seconds=Number($('#timeSelect').value);state.names=$('#namesInput').value.split(/[,，\n]/).map(x=>x.trim()).filter(Boolean);if(state.names.length<MODES[state.mode].count){toast(`此模式至少需要 ${MODES[state.mode].count} 個名稱`);return}state.round=1;state.groupIndex=0;state.used.clear();state.selectedPlayer=0;makePlayers();draw();resetTimer();renderMeta();$('#setupView').hidden=true;$('#gameView').hidden=false;persist();tone(660,.12)}
  function nextRound(skip=false){if(!skip){state.records.push({time:new Date().toISOString(),mode:MODES[state.mode].name,round:state.round,unit:UNITS[state.question.unit],difficulty:state.difficulty,question:state.question.prompt,answer:state.question.answer,players:state.players.map(p=>`${p.name}:${p.score}`).join('|')})}state.round++;state.groupIndex++;state.selectedPlayer=0;makePlayers();draw();resetTimer();renderMeta();persist();toast(skip?'已跳題並換上新題':'下一組上場！')}
  function csv(){if(!state.records.length){toast('目前沒有可匯出的戰績');return}const headers=['時間','模式','回合','單元','難度','題目','答案','成績'];const rows=state.records.map(r=>[r.time,r.mode,r.round,r.unit,r.difficulty,r.question,r.answer,r.players]);const text='\uFEFF'+[headers,...rows].map(row=>row.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.download=`數學王者競技場戰績_${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href)}
  function escapeHtml(s){return s.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
  $$('.mode-card').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;settingsToUI();persist()});$$('[data-difficulty]').forEach(b=>b.onclick=()=>{state.difficulty=b.dataset.difficulty;settingsToUI();persist()});$('#startBtn').onclick=newGame;$('#timerBtn').onclick=toggleTimer;$('#revealBtn').onclick=reveal;$('#skipBtn').onclick=()=>nextRound(true);$('#nextBtn').onclick=()=>nextRound(false);$('#homeBtn').onclick=()=>{resetTimer();$('#gameView').hidden=true;$('#setupView').hidden=false;settingsToUI()};$('#scoreControls').addEventListener('dblclick',()=>judge(true));$('#scoreControls').addEventListener('contextmenu',e=>{e.preventDefault();judge(false)});document.addEventListener('keydown',e=>{if(['INPUT','SELECT'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();toggleTimer()}if(e.key.toLowerCase()==='a')reveal();if(e.key.toLowerCase()==='s')nextRound(true);if(e.key.toLowerCase()==='n')nextRound(false);if(e.key.toLowerCase()==='f')$('#fullscreenBtn').click();if(['1','2','3'].includes(e.key)&&Number(e.key)<=state.players.length){state.selectedPlayer=Number(e.key)-1;renderPlayers()}if(e.key==='+')judge(true);if(e.key==='-')judge(false)});$('#soundBtn').onclick=()=>{state.sound=!state.sound;settingsToUI();persist();tone(600)};$('#motionBtn').onclick=()=>{state.reduced=!state.reduced;settingsToUI();persist()};$('#fullscreenBtn').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();$('#exportBtn').onclick=csv;$('#clearBtn').onclick=()=>{if(confirm('確定清除所有本機戰績？教師設定會保留。')){state.records=[];persist();settingsToUI();toast('戰績已清除')}};$('#helpBtn').onclick=()=>$('#helpDialog').showModal();$('.dialog-close').onclick=()=>$('#helpDialog').close();$('#unitSelect').onchange=e=>{state.unit=e.target.value;persist()};$('#timeSelect').onchange=e=>{state.seconds=Number(e.target.value);persist()};
  const correct=document.createElement('button');correct.textContent='✓ 答對 +100';correct.onclick=()=>judge(true);const wrong=document.createElement('button');wrong.textContent='✗ 答錯 −50';wrong.className='danger';wrong.onclick=()=>judge(false);$('#scoreControls').after(correct,wrong);settingsToUI();
})();
